#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( $1 * 90 / 100 ))

#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( $1 * 90 / 100 ))"

#!/bin/bash
# Total with 10% tax on the member price, rounded down.
m=$(( $1 * 90 / 100 ))
echo $(( m * 100 / 110 ))

#!/bin/bash
# Invoice line for a member order.
echo "member total $(( $1 * 90 / 100 ))"

#!/bin/bash
fail=0
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
exit $fail

#!/bin/bash
fail=0
[ "$(bash bin/total 1000)" = 990 ] || { echo "total 1000: expected 990, got $(bash bin/total 1000)"; fail=1; }
exit $fail

